create table if not exists groups (number text primary key, display_order integer not null unique);
create table if not exists people (id bigserial primary key, record_key integer not null unique, name text not null, note text not null default '', phone1 text not null default '', phone2 text not null default '', group_number text references groups(number), address text not null default '', role text not null default 'boy', qr_token text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
do $$ begin if exists (select 1 from information_schema.columns where table_name='people' and column_name='source_row') then alter table people rename column source_row to record_key; end if; end $$;
alter table people add column if not exists is_active boolean not null default true;
alter table people add column if not exists role text not null default 'boy';
alter table people add column if not exists qr_token text;
update people set qr_token = md5(random()::text || clock_timestamp()::text || id::text) where qr_token is null;
create unique index if not exists people_qr_token_idx on people(qr_token);
create table if not exists settings (key text primary key, value jsonb not null, updated_at timestamptz not null default now());
create table if not exists visit_records (person_id bigint not null references people(id) on delete cascade, visit_date date not null, recorded_at timestamptz not null default now(), primary key (person_id, visit_date));
create table if not exists call_assignments (week_start date not null, group_number text not null references groups(number), servant text not null, assigned_at timestamptz not null default now(), primary key (week_start, group_number));
create table if not exists call_records (person_id bigint not null references people(id) on delete cascade, week_start date not null, servant text not null default '', recorded_at timestamptz not null default now(), primary key (person_id, week_start));
create table if not exists attendance_records (person_id bigint not null references people(id) on delete cascade, attendance_type text not null check (attendance_type in ('choir','mass')), attendance_date date not null, recorded_at timestamptz not null default now(), primary key (person_id, attendance_type, attendance_date));
create table if not exists choir_evaluations (person_id bigint not null references people(id) on delete cascade, attendance_date date not null, points integer not null check (points between 0 and 10), updated_at timestamptz not null default now(), primary key (person_id, attendance_date));
create table if not exists learning_items (id bigserial primary key, lesson_date date not null, category text not null, title text not null, resource_url text not null, description text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table learning_items add column if not exists background_url text not null default '';
alter table learning_items add column if not exists links jsonb not null default '[]'::jsonb;
create index if not exists learning_items_date_idx on learning_items(lesson_date desc, category, id);
create table if not exists mass_schedules (id bigserial primary key, service_date date not null, service_time time not null, location text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists mass_schedules_date_idx on mass_schedules(service_date, service_time, id);
create table if not exists parent_notifications (id bigserial primary key, person_id bigint references people(id) on delete cascade, title text not null, body text not null, target_url text not null, event_key text, created_at timestamptz not null default now());
alter table parent_notifications add column if not exists event_key text;
create index if not exists parent_notifications_feed_idx on parent_notifications(created_at desc, person_id);
create unique index if not exists parent_notifications_event_key_idx on parent_notifications(event_key) where event_key is not null;
create table if not exists attendance_comments (person_id bigint not null references people(id) on delete cascade, attendance_type text not null check (attendance_type in ('choir','mass')), attendance_date date not null, comment text not null default '', recorded_at timestamptz not null default now(), primary key (person_id, attendance_type, attendance_date));
create table if not exists followup_notes (id bigserial primary key, person_id bigint not null references people(id) on delete cascade, servant text not null default '', note_type text not null check (note_type in ('visit','call')), note_date date not null, note text not null, created_at timestamptz not null default now());
create table if not exists followup_requests (id bigserial primary key, person_id bigint not null references people(id) on delete cascade, request_type text not null check (request_type in ('call','visit')), message text not null default '', status text not null default 'new' check (status in ('new','in_progress','done')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists followup_notes_date_idx on followup_notes(note_date desc, person_id);
create index if not exists people_group_idx on people(group_number, record_key);
drop index if exists visit_records_person_idx;
create index if not exists visit_records_date_idx on visit_records(visit_date, person_id);
drop index if exists call_records_person_idx;
create index if not exists call_records_week_idx on call_records(week_start, person_id);
drop index if exists attendance_person_idx;
create index if not exists attendance_records_date_idx on attendance_records(attendance_date, attendance_type, person_id);
create index if not exists choir_evaluations_date_idx on choir_evaluations(attendance_date desc, person_id);
create index if not exists followup_requests_person_idx on followup_requests(person_id, created_at desc);
create index if not exists followup_requests_created_idx on followup_requests(created_at desc);
